// 在 If-Match 下更新团队展示名并递增 revision。
func (q *Queries) UpdateTeam(ctx context.Context, arg UpdateTeamParams) (Team, error) {
	row := q.db.QueryRow(ctx, updateTeam,
		arg.DisplayName,
		arg.TenantID,
		arg.ID,
		arg.ExpectedRevision,
	)
	var i Team
	err := row.Scan(
		&i.TenantID,
		&i.ID,
		&i.Slug,
		&i.DisplayName,
		&i.Revision,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
